statements:
create extension if not exists "pgcrypto";
create type public.user_role as enum ('ceo','cro','coo_cfo','colaborador','cliente');
create type public.app_environment as enum ('executivo','comercial','operacional','portal');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text not null default '',role public.user_role not null default 'colaborador',phone text,avatar_url text,default_environment public.app_environment not null default 'executivo',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_profiles_role on public.profiles(role);
create function public.eh_interno() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('ceo','cro','coo_cfo','colaborador')); $$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1))) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.tocar_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now();return new;end; $$;
alter table public.profiles enable row level security;
create policy profiles_select_interno on public.profiles for select to authenticated using(public.eh_interno() or id=auth.uid());
create policy profiles_update_proprio on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create function public.proteger_cargo() returns trigger language plpgsql set search_path=public as $$ begin if new.role is distinct from old.role and auth.uid() is not null then raise exception 'Elevação de cargo não permitida pelo cliente';end if;return new;end; $$;
create trigger profiles_protege_cargo before update on public.profiles for each row execute function public.proteger_cargo();
revoke execute on function public.eh_interno() from public,anon;
grant execute on function public.eh_interno() to authenticated;
revoke execute on function public.handle_new_user() from public,anon,authenticated;
revoke execute on function public.tocar_updated_at() from public,anon,authenticated;
revoke execute on function public.proteger_cargo() from public,anon,authenticated;

create type public.lead_stage as enum ('novo','contato','qualificado','proposta','negociacao','ganho','perdido');create type public.lead_source as enum ('indicacao','site','instagram','linkedin','evento','outbound','outro');create type public.client_segment as enum ('audiovisual','marketing','estrategia','influencia','outro');
create table public.clientes(id uuid primary key default gen_random_uuid(),nome_fantasia text not null,razao_social text,documento text,segmento public.client_segment not null default 'outro',site text,contatos jsonb not null default '[]',responsavel_comercial_id uuid references public.profiles(id) on delete set null,observacoes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_clientes_responsavel on public.clientes(responsavel_comercial_id);
create trigger clientes_updated_at before update on public.clientes for each row execute function public.tocar_updated_at();
create table public.leads(id uuid primary key default gen_random_uuid(),nome text not null,empresa text not null,email text,telefone text,origem public.lead_source not null default 'site',etapa public.lead_stage not null default 'novo',valor_estimado bigint not null default 0,responsavel_id uuid references public.profiles(id) on delete set null,observacoes text,proximo_contato timestamptz,cliente_id uuid references public.clientes(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_leads_etapa on public.leads(etapa);create index idx_leads_responsavel on public.leads(responsavel_id);
create trigger leads_updated_at before update on public.leads for each row execute function public.tocar_updated_at();
alter table public.clientes enable row level security;alter table public.leads enable row level security;
create policy clientes_interno_crud on public.clientes for all to authenticated using(public.eh_interno()) with check(public.eh_interno());
create policy leads_interno_crud on public.leads for all to authenticated using(public.eh_interno()) with check(public.eh_interno());

create type public.project_status as enum ('briefing','planejamento','producao','revisao','aprovacao','entregue','pausado');create type public.task_status as enum ('pendente','em_andamento','concluida','bloqueada');create type public.task_priority as enum ('baixa','media','alta');
create table public.projetos(id uuid primary key default gen_random_uuid(),cliente_id uuid not null references public.clientes(id) on delete restrict,titulo text not null,tipo_servico text not null,status public.project_status not null default 'briefing',responsavel_id uuid references public.profiles(id) on delete set null,data_inicio timestamptz,data_entrega_prevista timestamptz,data_entrega_real timestamptz,orcamento bigint not null default 0,descricao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_projetos_cliente on public.projetos(cliente_id);create index idx_projetos_status on public.projetos(status);
create trigger projetos_updated_at before update on public.projetos for each row execute function public.tocar_updated_at();
create table public.tarefas(id uuid primary key default gen_random_uuid(),projeto_id uuid references public.projetos(id) on delete cascade,titulo text not null,descricao text,status public.task_status not null default 'pendente',prioridade public.task_priority not null default 'media',responsavel_id uuid references public.profiles(id) on delete set null,prazo timestamptz,concluida_em timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_tarefas_projeto on public.tarefas(projeto_id);create index idx_tarefas_responsavel on public.tarefas(responsavel_id);create index idx_tarefas_prazo on public.tarefas(prazo);
create trigger tarefas_updated_at before update on public.tarefas for each row execute function public.tocar_updated_at();
alter table public.projetos enable row level security;alter table public.tarefas enable row level security;
create policy projetos_interno_crud on public.projetos for all to authenticated using(public.eh_interno()) with check(public.eh_interno());
create policy tarefas_interno_crud on public.tarefas for all to authenticated using(public.eh_interno()) with check(public.eh_interno());

create type public.transaction_kind as enum ('entrada','saida');create type public.finance_category as enum ('projeto','servico','produto','prazo_labore','reembolso','distribuicao_lucros','imposto','equipe','ferramenta','infraestrutura','marketing','outro');
create table public.transacoes_financeiras(id uuid primary key default gen_random_uuid(),tipo public.transaction_kind not null,categoria public.finance_category not null default 'outro',descricao text not null,valor bigint not null check(valor>=0),projeto_id uuid references public.projetos(id) on delete set null,cliente_id uuid references public.clientes(id) on delete set null,vencimento timestamptz not null,pago boolean not null default false,pago_em timestamptz,metodo_pagamento text,criado_por uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_transacoes_vencimento on public.transacoes_financeiras(vencimento);create index idx_transacoes_pago on public.transacoes_financeiras(pago);create index idx_transacoes_projeto on public.transacoes_financeiras(projeto_id);
create trigger transacoes_updated_at before update on public.transacoes_financeiras for each row execute function public.tocar_updated_at();
create view public.vencimentos_em_aberto with(security_invoker=true) as select id,tipo,categoria,descricao,valor,vencimento,projeto_id,cliente_id,(vencimento<now()) as vencida from public.transacoes_financeiras where not pago order by vencimento asc;
alter table public.transacoes_financeiras enable row level security;
create policy transacoes_interno_crud on public.transacoes_financeiras for all to authenticated using(public.eh_interno()) with check(public.eh_interno());
revoke select on public.vencimentos_em_aberto from public,anon;grant select on public.vencimentos_em_aberto to authenticated;

create type public.decision_status as enum('rascunho','aberta','aprovada','reprovada','cancelada');create type public.approval_rule as enum('unanimidade','maioria','socio_presente','livre');create type public.vote_choice as enum('favor','contra','abstencao');
create table public.decisoes(id uuid primary key default gen_random_uuid(),titulo text not null,descricao text not null,solicitante_id uuid not null references public.profiles(id) on delete restrict,justificativa text,impacto_financeiro bigint,participantes uuid[] not null default '{}',regra_aprovacao public.approval_rule not null default 'maioria',status public.decision_status not null default 'aberta',prazo timestamptz,historico jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_decisoes_status on public.decisoes(status);create index idx_decisoes_solicitante on public.decisoes(solicitante_id);
create trigger decisoes_updated_at before update on public.decisoes for each row execute function public.tocar_updated_at();
create function public.decisao_registrar_evento() returns trigger language plpgsql set search_path=public as $$ declare evento jsonb;begin if tg_op='INSERT' then evento=jsonb_build_object('evento','criada','usuarioId',new.solicitante_id,'detalhe','Solicitação aberta','em',now());new.historico=new.historico||jsonb_build_array(evento);elsif tg_op='UPDATE' and new.status is distinct from old.status then evento=jsonb_build_object('evento',new.status,'usuarioId',auth.uid(),'detalhe',concat('Status: ',old.status,' → ',new.status),'em',now());new.historico=new.historico||jsonb_build_array(evento);end if;return new;end; $$;
create trigger decisoes_evento before insert or update on public.decisoes for each row execute function public.decisao_registrar_evento();
create function public.proteger_historico() returns trigger language plpgsql set search_path=public as $$ begin if new.historico is distinct from old.historico then raise exception 'O histórico da decisão é gerenciado pelo sistema';end if;return new;end; $$;
create trigger decisoes_01_protege_historico before update on public.decisoes for each row execute function public.proteger_historico();
create table public.decisao_votos(decisao_id uuid not null references public.decisoes(id) on delete cascade,socio_id uuid not null references public.profiles(id) on delete cascade,voto public.vote_choice not null,comentario text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),primary key(decisao_id,socio_id));
create index idx_decisao_votos_socio on public.decisao_votos(socio_id);
create function public.tocar_voto_atualizado_em() returns trigger language plpgsql set search_path=public as $$ begin new.atualizado_em=now();return new;end; $$;
create trigger decisao_votos_updated_at before update on public.decisao_votos for each row execute function public.tocar_voto_atualizado_em();
alter table public.decisao_votos enable row level security;
create policy decisao_votos_interno_select on public.decisao_votos for select to authenticated using(public.eh_interno());
create policy decisao_votos_socio_insert on public.decisao_votos for insert to authenticated with check(socio_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo')) and exists(select 1 from public.decisoes d where d.id=decisao_id and d.status='aberta'));
create policy decisao_votos_socio_update on public.decisao_votos for update to authenticated using(socio_id=auth.uid()) with check(socio_id=auth.uid() and exists(select 1 from public.decisoes d where d.id=decisao_id and d.status='aberta'));
revoke execute on function public.decisao_registrar_evento() from public,anon,authenticated;
revoke execute on function public.proteger_historico() from public,anon,authenticated;
revoke execute on function public.tocar_voto_atualizado_em() from public,anon,authenticated;
alter table public.decisoes enable row level security;
create policy decisoes_interno_select on public.decisoes for select to authenticated using(public.eh_interno());
create policy decisoes_socio_insert on public.decisoes for insert to authenticated with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo')));
create policy decisoes_socio_update on public.decisoes for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo')));

create table public.automacoes(id uuid primary key default gen_random_uuid(),nome text not null,entidade text not null,entidade_id text not null,payload jsonb not null default '{}',resultado text,erro text,executada_em timestamptz not null default now(),constraint automacoes_unica unique(nome,entidade,entidade_id));
create index idx_automacoes_entidade on public.automacoes(entidade,entidade_id);
create function public.lead_ganho_registrar() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.etapa='ganho' and (tg_op='INSERT' or old.etapa is distinct from 'ganho') then insert into public.automacoes(nome,entidade,entidade_id,payload,resultado) values('venda_fechada','lead',new.id::text,jsonb_build_object('lead',new.nome,'empresa',new.empresa,'valor_estimado',new.valor_estimado),'evento registrado — materialização do cliente/projeto na Fase 2') on conflict(nome,entidade,entidade_id) do nothing;end if;return new;end; $$;
create trigger lead_ganho_evento after insert or update on public.leads for each row execute function public.lead_ganho_registrar();
revoke execute on function public.lead_ganho_registrar() from public,anon,authenticated;
alter table public.automacoes enable row level security;
create policy automacoes_interno_select on public.automacoes for select to authenticated using(public.eh_interno());

-- Segurança de onboarding: contas novas nunca recebem acesso interno automaticamente.
alter table public.profiles alter column role set default 'cliente';
-- Trigger de RLS automático não deve ser invocável por usuários da API.
revoke execute on function public.rls_auto_enable() from public,anon,authenticated;
-- Votos só podem ser alterados enquanto a decisão permanece aberta.
drop policy if exists decisao_votos_socio_update on public.decisao_votos;
create policy decisao_votos_socio_update on public.decisao_votos for update to authenticated
using(socio_id=auth.uid() and exists(select 1 from public.decisoes d where d.id=decisao_id and d.status='aberta'))
with check(socio_id=auth.uid() and exists(select 1 from public.decisoes d where d.id=decisao_id and d.status='aberta'));
-- Dados de identidade e metadados de auditoria devem ser imutáveis pelo usuário final.
create or replace function public.proteger_identidade_perfil() returns trigger language plpgsql set search_path=public as $$
begin
 if auth.uid() is not null and (
  new.id is distinct from old.id or new.email is distinct from old.email
  or new.role is distinct from old.role or new.default_environment is distinct from old.default_environment
  or new.created_at is distinct from old.created_at
 ) then raise exception 'Campos protegidos do perfil não podem ser alterados pelo cliente';
 end if;
 return new;
end;$$;
create trigger profiles_01_protege_identidade before update on public.profiles for each row execute function public.proteger_identidade_perfil();
revoke execute on function public.proteger_identidade_perfil() from public,anon,authenticated;

-- Permissões explícitas; políticas RLS existentes permanecem intactas.
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('profiles','clientes','leads','projetos','tarefas','transacoes_financeiras','decisoes','decisao_votos','automacoes') AND NOT c.relrowsecurity) THEN RAISE EXCEPTION 'RLS deve estar habilitado'; END IF;
END $$;
GRANT SELECT ON public.profiles,public.clientes,public.leads,public.projetos,public.tarefas,public.transacoes_financeiras,public.decisoes,public.decisao_votos,public.automacoes TO authenticated;
GRANT INSERT, UPDATE ON public.clientes,public.leads,public.projetos,public.tarefas,public.transacoes_financeiras,public.decisoes,public.decisao_votos TO authenticated;
GRANT UPDATE(full_name,phone,avatar_url) ON public.profiles TO authenticated;
REVOKE TRUNCATE, REFERENCES, TRIGGER ON public.profiles,public.clientes,public.leads,public.projetos,public.tarefas,public.transacoes_financeiras,public.decisoes,public.decisao_votos,public.automacoes FROM anon,authenticated;
